export type TravelDirection = "up" | "down";

export interface LiftSnapshot {
  readonly floor: number;
  readonly direction: TravelDirection;
}

export class LiftShaft {
  private current: { floor: number; direction: TravelDirection } | undefined;

  constructor(
    private readonly lowestFloor: number,
    private readonly highestFloor: number,
  ) {
    if (
      !Number.isFinite(lowestFloor) ||
      !Number.isInteger(lowestFloor) ||
      !Number.isFinite(highestFloor) ||
      !Number.isInteger(highestFloor) ||
      lowestFloor > highestFloor
    ) {
      throw new RangeError("Invalid shaft bounds");
    }
  }

  install(): LiftSnapshot {
    this.current = { floor: this.lowestFloor, direction: "up" };
    return this.snapshot()!;
  }

  place(floor: number, direction: TravelDirection): boolean {
    if (
      this.current === undefined ||
      !Number.isFinite(floor) ||
      !Number.isInteger(floor) ||
      floor < this.lowestFloor ||
      floor > this.highestFloor ||
      (direction !== "up" && direction !== "down")
    ) {
      return false;
    }
    this.current = { floor, direction };
    return true;
  }

  reverse(): boolean {
    if (this.current === undefined) return false;
    this.current.direction = this.current.direction === "up" ? "down" : "up";
    return true;
  }

  advance(): boolean {
    if (this.current === undefined) return false;
    const next = this.current.floor + (this.current.direction === "up" ? 1 : -1);
    if (next < this.lowestFloor || next > this.highestFloor + 1) return false;
    this.current.floor = next;
    return true;
  }

  snapshot(): LiftSnapshot | undefined {
    return this.current === undefined ? undefined : { ...this.current };
  }
}

