import { LiftShaft, TravelDirection } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function rangeError(action: () => void, message: string): void {
  try { action(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: expected RangeError`);
}

rangeError(() => new LiftShaft(NaN, 2), 'NaN lower bound');
rangeError(() => new LiftShaft(0, Infinity), 'infinite upper bound');
rangeError(() => new LiftShaft(0.5, 2), 'fractional lower bound');
rangeError(() => new LiftShaft(3, 2), 'reversed bounds');

const lift = new LiftShaft(-2, 2);
equal(lift.snapshot(), undefined, 'new shaft is uninstalled');
equal(lift.advance(), false, 'uninstalled advance fails');
equal(lift.reverse(), false, 'uninstalled reverse fails');
equal(lift.place(0, 'down'), false, 'uninstalled placement fails');

const installed = lift.install();
equal(installed.floor, -2, 'install uses lowest floor');
equal(installed.direction, 'up', 'install points upward');
assert(lift.snapshot() !== installed, 'install snapshot is not internal state');
(installed as { floor: number; direction: TravelDirection }).floor = 99;
equal(lift.snapshot()!.floor, -2, 'install snapshot cannot mutate state');

equal(lift.advance(), true, 'advance upward succeeds');
equal(lift.snapshot()!.floor, -1, 'advance moves exactly one floor');
equal(lift.place(2, 'up'), true, 'valid placement succeeds');
const beforeBoundary = lift.snapshot()!;
equal(lift.advance(), false, 'cannot cross upper boundary');
equal(lift.snapshot()!.floor, beforeBoundary.floor, 'failed boundary move preserves floor');
equal(lift.snapshot()!.direction, beforeBoundary.direction, 'failed boundary move preserves direction');
equal(lift.reverse(), true, 'reverse succeeds');
equal(lift.snapshot()!.direction, 'down', 'direction reverses');
equal(lift.advance(), true, 'advance downward succeeds');
equal(lift.snapshot()!.floor, 1, 'downward movement is one floor');

const stable = lift.snapshot()!;
equal(lift.place(3, 'down'), false, 'out-of-range placement fails');
equal(lift.place(0.25, 'up'), false, 'fractional placement fails');
equal(lift.place(NaN, 'up'), false, 'NaN placement fails');
equal(lift.place(0, 'sideways' as TravelDirection), false, 'malformed direction fails');
equal(lift.snapshot()!.floor, stable.floor, 'invalid placement preserves floor');
equal(lift.snapshot()!.direction, stable.direction, 'invalid placement preserves direction');

const first = lift.snapshot()!;
const second = lift.snapshot()!;
assert(first !== second, 'each snapshot is newly allocated');
(first as { floor: number }).floor = -100;
equal(lift.snapshot()!.floor, 1, 'snapshot mutation is isolated');

lift.place(0, 'down');
lift.install();
equal(lift.snapshot()!.floor, -2, 'reinstall resets floor');
equal(lift.snapshot()!.direction, 'up', 'reinstall resets direction');

const single = new LiftShaft(4, 4);
single.install();
equal(single.advance(), false, 'one-floor shaft cannot advance upward');
single.reverse();
equal(single.advance(), false, 'one-floor shaft cannot advance downward');
equal(single.snapshot()!.floor, 4, 'one-floor cabin remains in place');

